function commerceProductImage(product){
 if(!product)return "";
 // A saved empty/null image is authoritative; never restore a catalogue fallback.
 const current=Object.prototype.hasOwnProperty.call(product,"image_url")?product.image_url:
  Object.prototype.hasOwnProperty.call(product,"image")?product.image:product.imageUrl;
 return current==null?"":String(current).trim();
}
