function footer(){return `<footer class="footer"><div class="footerin"><div><img src="${esc(DEFAULT_SETTINGS.logoUrl)}" alt="Okyanus EDT" style="width:86px;height:86px;object-fit:contain;background:#fff;border-radius:14px"><h4 id="footerSiteTitle">Okyanus EDT</h4><p><b data-contact-name>${esc(DEFAULT_SETTINGS.contactName)}</b> \u00b7 <span id="footerPhone">${esc(DEFAULT_SETTINGS.phone)}</span><br><b data-contact-name-2>${esc(DEFAULT_SETTINGS.secondContactName)}</b> \u00b7 <span id="footerPhone2">${esc(DEFAULT_SETTINGS.secondPhone)}</span></p><p id="footerText">${esc(DEFAULT_SETTINGS.footerText)}</p><a id="footerEmail" href="mailto:${esc(DEFAULT_SETTINGS.email)}">${esc(DEFAULT_SETTINGS.email)}</a><a href="/iletisim#sales-team">WhatsApp / Sat\u0131\u015f Ekibi</a></div><div><h4>Al\u0131\u015fveri\u015f</h4><a href="/urunler">T\u00fcm \u00dcr\u00fcnler</a><a href="/kampanyalar">Kampanyalar</a><a href="/urunler?filter=new">Yeni \u00dcr\u00fcnler</a><a href="/markalar">Markalar</a></div><div><h4>Destek</h4><a href="/">Ana Sayfa</a><a href="/yardim">Site Yard\u0131m</a><a href="/iletisim">Bize Ula\u015f\u0131n</a><a href="/yardim#teslimat">Teslimat</a><a href="/yardim#iade">\u0130ade</a><a data-admin-link href="/yonetici">\ud83d\udd12 Y\u00f6netici Paneli</a></div><div><h4>Okyanus Ara\u00e7lar\u0131</h4><a href="/icerik-studyo">\u0130\u00e7erik St\u00fcdyo</a><a href="/fotografla-teklif">Foto\u011frafla Teklif</a><a href="/dijital-menu">Dijital Men\u00fc</a><a href="/hakkimizda">Hakk\u0131m\u0131zda</a></div><div><h4>E-b\u00fclten</h4><p>Kampanya ve yeni \u00fcr\u00fcn duyurular\u0131 i\u00e7in a\u00e7\u0131k onayla kaydolun.</p><p><a href="/e-bulten">Haftalık E-bülteni Oku →</a></p><form id="newsletterForm" class="form"><input name="name" placeholder="Ad Soyad"><input name="email" type="email" required placeholder="E-posta"><label><input name="consent" type="checkbox" required style="width:auto"> E-b\u00fclten ileti\u015fimine onay veriyorum.</label><button type="submit">Kaydol</button><small id="newsletterResult"></small></form></div></div></footer><script>(function(){const f=document.getElementById("newsletterForm"),o=document.getElementById("newsletterResult");if(!f||!o)return;f.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f));o.textContent="Kaydediliyor\u2026";try{const r=await fetch("/api/newsletter",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({name:d.name||"",email:d.email||"",consent:!!f.elements.consent.checked})}),j=await r.json();o.textContent=r.ok?"E-b\u00fclten kayd\u0131n\u0131z al\u0131nd\u0131.":(j.error||"Kay\u0131t yap\u0131lamad\u0131.");if(r.ok)f.reset()}catch(_){o.textContent="Ba\u011flant\u0131 hatas\u0131."}}})();</script>`}
