async function commerceMember(request,env){
 const DB=env?.DB;if(!DB)return null;let token='';try{const cookie=(request.headers.get('cookie')||'').split(';').map(x=>x.trim()).find(x=>x.startsWith('__Host-oky_session='));token=cookie?decodeURIComponent(cookie.slice(cookie.indexOf('=')+1)):''}catch{}if(!token)return null;
 const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(token)))].map(x=>x.toString(16).padStart(2,'0')).join('');
 try{return await DB.prepare("SELECT u.id user_id,s.business_id FROM member_sessions_v3 s JOIN member_users_v3 u ON u.id=s.user_id JOIN member_business_members_v3 bm ON bm.user_id=u.id AND bm.business_id=s.business_id JOIN member_businesses_v3 b ON b.id=s.business_id AND b.status='active' WHERE s.token_hash=? AND s.revoked_at IS NULL AND s.expires_at>? AND u.status='active' LIMIT 1").bind(hash,new Date().toISOString()).first()}catch{return null}
}
async function commerceAccount(request,env){
 const me=await commerceMember(request,env);if(!me)return json({ok:false,error:'UNAUTHENTICATED'},401);
 const DB=env.DB;try{const tables=new Set((await DB.prepare("SELECT name FROM sqlite_master WHERE type='table'").all()).results.map(x=>x.name));let quotes=[],orders=[];
 if(tables.has('b2b_quotes_v1')){quotes=(await DB.prepare('SELECT id,quote_no,created_at,status,total,currency FROM b2b_quotes_v1 WHERE customer_id=? AND business_id=? ORDER BY created_at DESC LIMIT 100').bind(me.user_id,me.business_id).all()).results||[];if(tables.has('b2b_quote_items_v1'))for(const q of quotes)q.items=(await DB.prepare('SELECT product_name,unit,quantity FROM b2b_quote_items_v1 WHERE quote_id=?').bind(q.id).all()).results||[]}
 if(tables.has('b2b_orders_v1'))orders=(await DB.prepare('SELECT id,order_no,created_at,status,total,currency FROM b2b_orders_v1 WHERE customer_id=? AND business_id=? ORDER BY created_at DESC LIMIT 100').bind(me.user_id,me.business_id).all()).results||[];
 return json({ok:true,quotes,orders})}catch{return json({ok:false,error:'HISTORY_UNAVAILABLE',message:'Ge\u00e7mi\u015f \u015fu anda y\u00fcklenemiyor.'},503)}
}

