function openingCampaignSettings(input={}){
 const field=(name,fallback)=>Object.prototype.hasOwnProperty.call(input,name)?String(input[name]??''):fallback;
 const enabled=!['false','0','off'].includes(field('openingCampaignEnabled','true').toLowerCase());
 const safeUrl=(value,fallback)=>{const v=String(value||'').trim();return /^\/(?!\/)/.test(v)||/^https:\/\//i.test(v)?v:fallback};
 const rawImage=field('openingCampaignImage',OPENING_CAMPAIGN_IMAGE);
 const image=enabled&&(/^data:image\/(?:png|jpeg|webp);base64,[a-z0-9+/=]+$/i.test(rawImage)||/^https:\/\//i.test(rawImage)||/^\/(?!\/)/.test(rawImage))?rawImage:'';
 const title=field('openingCampaignTitle','Okyanus EDT'),description=field('openingCampaignDescription','Deniz \u00fcr\u00fcnleri, donuk \u00fcr\u00fcnler ve temel g\u0131dada \u00fcr\u00fcnlerinizi se\u00e7in, teklifinizi al\u0131n.');
 const ctaText=field('openingCampaignCtaText','\u00dcr\u00fcn Se\u00e7 \u2022 Teklif Al'),ctaUrl=safeUrl(field('openingCampaignCtaUrl','/urunler'),'/urunler');
 const photoCtaText=field('openingCampaignPhotoCtaText','Listeni Foto\u011frafla G\u00f6nder'),photoCtaUrl=safeUrl(field('openingCampaignPhotoCtaUrl','/fotografla-teklif'),'/fotografla-teklif');
 let hash=2166136261;for(const ch of JSON.stringify([enabled,image,title,description,ctaText,ctaUrl,photoCtaText,photoCtaUrl]))hash=Math.imul(hash^ch.charCodeAt(0),16777619)>>>0;
 return {enabled,image,title,description,ctaText,ctaUrl,photoCtaText,photoCtaUrl,key:'opening-v26-'+hash.toString(16)};
}
