    const brandCols=hasBrands?await columns('oky_brands_v1'):new Set(),priceCols=hasPrices?await columns('b2b_prices_v1'):new Set();
    const metaCols=','+['description','seo_title','seo_description','featured','sort_order','brand_id'].map(n=>pick(mCols,'m',n,['featured','sort_order'].includes(n)?'0':'NULL')).join(',')+','+(mCols.has('brand_id')&&brandCols.has('id')&&brandCols.has('name')?'(SELECT name FROM oky_brands_v1 b WHERE b.id=m.brand_id'+(brandCols.has('active')?' AND b.active=1':'')+' LIMIT 1)':'NULL')+' AS brand';
