    const sql='SELECT '+['id','source_product_id','name','category','unit','package_text','image_url','stock_status','active'].map(n=>pick(pCols,'p',n,n==='active'?'1':'NULL',n==='image_url'?'image':n)).join(',')+','+priceExpr+' AS basePrice'+metaCols+commerceCols+' FROM b2b_products_v1 p'+joins+(pCols.has('active')?' WHERE p.active=1':'')+' ORDER BY '+order;
    const rows=(await DB.prepare(sql).all()).results||[];homepageAuthoritative=!!hasMeta&&mCols.has("featured");
