 try{const DB=commerceDatabase(env);if(DB){const has=await DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='oky_storefront_settings_v1'").first();if(has){const row=await DB.prepare("SELECT value FROM oky_storefront_settings_v1 WHERE key='adminUrl' LIMIT 1").first();if(row?.value)target=String(row.value).trim()}}}catch(_){}
 if(!/^https:\/\//i.test(target))return html('<!doctype html><html lang="tr"><meta charset="utf-8"><link rel="manifest" href="/manifest.webmanifest"><meta name="theme-color" content="#07345e"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Y\u00f6netici | Okyanus EDT</title><body style="font-family:Arial;padding:30px"><h1>Y\u00f6netici paneli ba\u011flant\u0131s\u0131 tan\u0131ml\u0131 de\u011fil.</h1><p>ZAMAN/Admin Worker taraf\u0131ndaki <b>/commerce</b> panelini kullan\u0131n.</p><p><a href="/">\u2190 Ana Sayfa</a></p></body></html>',503);
 return Response.redirect(target,302);
