function newsletterWeek(now=new Date()){
 const fmt=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Istanbul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'});
 const parts=d=>Object.fromEntries(fmt.formatToParts(d).filter(p=>p.type!=='literal').map(p=>[p.type,Number(p.value)]));
 const p=parts(now),day=Date.UTC(p.year,p.month-1,p.day),monday=day-((new Date(day).getUTCDay()+6)%7)*86400000;
 const midnight=local=>{let instant=local;for(let i=0;i<3;i++){const q=parts(new Date(instant));instant+=local-Date.UTC(q.year,q.month-1,q.day,q.hour,q.minute,q.second)}return new Date(instant).toISOString()};
 return {weekKey:new Date(monday).toISOString().slice(0,10),periodEnd:new Date(monday+6*86400000).toISOString().slice(0,10),startsAt:midnight(monday),nextRefreshAt:midnight(monday+7*86400000),timeZone:'Europe/Istanbul'};
}
