function newsletterPrice(value){return value!==null&&value!==undefined&&String(value).trim()!==''&&Number.isFinite(Number(value))&&Number(value)>=0?Number(value):null}
function newsletterEdition(catalog,now=new Date()){
 const week=newsletterWeek(now),hash=s=>{let h=2166136261;for(const c of s){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0},seen=new Set();
 const source=Array.isArray(catalog.products)?catalog.products:[];
 const pictured=source.filter(p=>{const image=String(p.image??p.image_url??'');return /^data:image\/(?:png|jpeg|webp|gif);base64,/i.test(image)||!!newsletterSafeUrl(image,'')});
 const pool=pictured.length>=12?pictured:source;
 const ranked=pool.filter(p=>{const id=String(p.source_product_id||p.id||'');if(!id||!p.name||seen.has(id))return false;seen.add(id);return true}).map(p=>({p,score:hash(week.weekKey+'|'+String(p.source_product_id||p.id))})).sort((a,b)=>a.score-b.score||String(a.p.id).localeCompare(String(b.p.id)));
 const picked=[],categories=new Set();for(const r of ranked){const category=String(r.p.category||'');if(!categories.has(category)){picked.push(r.p);categories.add(category)}if(picked.length===12)break}for(const r of ranked){if(picked.length===12)break;if(!picked.includes(r.p))picked.push(r.p)}
 const products=picked.map(p=>{const id=String(p.source_product_id||p.id),price=newsletterPrice(p.effectivePrice??p.price??p.sale_price??p.list_price),listPrice=newsletterPrice(p.listPrice??p.list_price),rawImage=String(p.image??p.image_url??'');return {id,name:String(p.name),brand:String(p.brand||''),category:String(p.category||''),package:String(p.package_text||p.package||p.amount||''),unit:String(p.unit||'Adet'),price,listPrice:listPrice!==null&&price!==null&&listPrice>price?listPrice:null,currency:'TRY',image:/^data:image\/(?:png|jpeg|webp|gif);base64,/i.test(rawImage)?rawImage:newsletterSafeUrl(rawImage,''),url:'/urun/'+encodeURIComponent(id),campaignLabel:String(p.campaignLabel||'')}});
 return {ok:true,...week,title:'Okyanus EDT Haftalık E-bülten',generatedAt:now.toISOString(),products,campaigns:(Array.isArray(catalog.campaigns)?catalog.campaigns:[]).slice(0,6).map(c=>({id:c.id,title:String(c.title||'Kampanya'),description:String(c.description||''),url:newsletterSafeUrl(c.cta_url,'/kampanyalar'),ctaText:String(c.cta_text||'Kampanyayı incele')}))};
}
async function newsletterRead(env,now=new Date()){
 const catalog=await (await storefront(env)).json();
 if(!catalog.catalogAuthoritative&&typeof ACTIVE_PRODUCT_CATALOG!=='undefined'){const ids=new Set(catalog.products.map(p=>String(p.source_product_id||p.id)));for(const p of ACTIVE_PRODUCT_CATALOG){const id=String(p.source_product_id||p.id);if(!ids.has(id)){catalog.products.push({...p,image:commerceProductImage(p)});ids.add(id)}}}
 return newsletterEdition(catalog,now);
}
function weeklyNewsletterTeaser(){return '<section class="section homeNewsletter"><article class="promo dark"><p>HER PAZARTESİ YENİ SAYI</p><h2>Haftalık E-bülten</h2><p>Haftanın ürün seçkisi ve güncel kampanyalar bir arada.</p><a class="btn" href="/e-bulten">E-bülteni oku →</a></article></section>'}
function newsletterPage(edition){
 const date=s=>new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Istanbul'}).format(new Date(s+'T12:00:00Z'));
 const money=n=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY'}).format(n);
 const cards=edition.products.map(p=>'<article class="weeklyCard"><a class="weeklyImage" href="'+esc(p.url)+'">'+(p.image?'<img loading="lazy" src="'+esc(p.image)+'" alt="'+esc(p.name)+'">':'<span>'+esc(p.category||'Okyanus EDT')+'</span>')+'</a><div class="weeklyCardBody"><small>'+esc(p.brand||p.category)+'</small><h3><a href="'+esc(p.url)+'">'+esc(p.name)+'</a></h3><p>'+esc(p.package)+'</p><div class="weeklyPrice">'+(p.listPrice!==null?'<del>'+esc(money(p.listPrice))+'</del> ':'')+(p.price===null?'Fiyat için teklif alın':esc(money(p.price))+' <small>/ '+esc(p.unit)+'</small>')+'</div><a class="weeklyLink" href="'+esc(p.url)+'">Ürünü incele →</a></div></article>').join('');
 const campaigns=edition.campaigns.map(c=>'<article class="weeklyCampaign"><h3>'+esc(c.title)+'</h3><p>'+esc(c.description)+'</p><a href="'+esc(c.url)+'">'+esc(c.ctaText)+' →</a></article>').join('');
 const body='<style>.weekly{padding-bottom:40px}.weeklyHero{background:#052f50;color:white;border-radius:24px;padding:clamp(24px,5vw,64px);margin:24px 0 32px;position:relative;overflow:hidden}.weeklyHero:after{content:"";position:absolute;width:240px;height:240px;border:40px solid #e8b95630;border-radius:50%;right:-110px;top:-80px;pointer-events:none}.weeklyHero h1{font-size:clamp(30px,5vw,56px);line-height:1.05;max-width:650px;margin:16px 0}.weeklyHero p{max-width:600px;color:#e1edf5}.weeklyEyebrow{letter-spacing:.14em;color:#f1c76d;font-size:12px;font-weight:800}.weeklyGrid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:16px}.weeklyCard{border:1px solid #dfebf2;border-radius:16px;overflow:hidden;background:white;min-width:0}.weeklyImage{display:flex;align-items:center;justify-content:center;aspect-ratio:1;background:#f8fafb;padding:10px;color:#466477;text-align:center}.weeklyImage img{width:100%;height:100%;object-fit:contain}.weeklyCardBody{padding:14px}.weeklyCard h3{font-size:15px;line-height:1.4;margin:8px 0;overflow-wrap:anywhere}.weeklyCard p{font-size:12px;color:#526879;min-height:18px}.weeklyCard small{font-size:11px;color:#647987}.weeklyPrice{font-weight:800;color:#073b60;font-size:16px;margin:12px 0;overflow-wrap:anywhere}.weeklyPrice del{font-size:11px;color:#647987;font-weight:400;display:block}.weeklyLink{font-size:12px;font-weight:700}.weeklyCampaigns{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.weeklyCampaign{background:#eef6fa;padding:24px;border-radius:16px}.weeklyNote{font-size:13px;color:#526879;margin-top:24px}@media(max-width:1000px){.weeklyGrid{grid-template-columns:repeat(3,minmax(0,1fr))}.weeklyCampaigns{grid-template-columns:1fr}}@media(max-width:600px){.weeklyGrid{gap:7px}.weeklyCardBody{padding:8px}.weeklyCard h3{font-size:12px}.weeklyPrice{font-size:13px}.weeklyLink{font-size:11px}.weeklyHero{border-radius:16px}.weeklyImage{padding:5px}}</style><main class="wrap weekly"><section class="weeklyHero"><span class="weeklyEyebrow">HAFTALIK E-BÜLTEN</span><h1>İşletmeniz için haftanın seçkisi</h1><p>'+esc(date(edition.weekKey))+' – '+esc(date(edition.periodEnd))+'</p><p>Ürünleri keşfedin, aktif kampanyaları inceleyin ve ihtiyacınıza uygun teklif oluşturun.</p><a class="btn" href="/urunler">Tüm ürünleri keşfet →</a></section><section><div class="sectionhead"><h2>Haftanın ürünleri</h2><a href="/urunler">Kataloğu aç →</a></div><div class="weeklyGrid">'+cards+'</div>'+(cards?'':'<p>Ürün seçkisi yakında burada yayınlanacak.</p>')+'</section>'+(campaigns?'<section class="section"><div class="sectionhead"><h2>Aktif kampanyalar</h2><a href="/kampanyalar">Tüm kampanyalar →</a></div><div class="weeklyCampaigns">'+campaigns+'</div></section>':'')+'<p class="weeklyNote">Yeni sayı her pazartesi yayınlanır. Fiyatlar ve stok bilgileri ürün sayfasında güncellenir.</p>'+contactStrip()+'</main>';
 const script='(function(){var week='+JSON.stringify(edition.weekKey)+',next='+JSON.stringify(edition.nextRefreshAt)+';async function refresh(){try{var r=await fetch("/api/newsletter",{cache:"no-store"});if(!r.ok)return;var e=await r.json();if(e.weekKey!==week)location.reload()}catch(_){}}setTimeout(refresh,Math.max(1000,new Date(next).getTime()-Date.now()+500));document.addEventListener("visibilitychange",function(){if(!document.hidden)refresh()})})();';
 return commerceClientShell(edition.title,body,script).replace('</head>','<meta name="description" content="Okyanus EDT haftalık ürün seçkisi ve aktif kampanyalar. Her pazartesi yeni sayı."></head>');
}
/* WEEKLY_NEWSLETTER_END */

export async function commerceRoute(request,env){
 const u=new URL(request.url),p=u.pathname.length>1&&u.pathname.endsWith("/")?u.pathname.slice(0,-1):u.pathname,m=request.method;
 if(!["GET","HEAD"].includes(m)&&p!=="/api/storefront-v2"&&p!=="/api/newsletter")return null;
 if((m==="GET"||m==="HEAD")&&p==="/")return html(home(await openingCampaignRead(env)));
 if((m==="GET"||m==="HEAD")&&p==="/yonetici")return await adminPanelRedirect(env);
 if((m==="GET"||m==="HEAD")&&(p==="/yardim"||p==="/site-yardim"))return html(help());
 if((m==="GET"||m==="HEAD")&&p==="/iletisim")return html(contact());
 if((m==="GET"||m==="HEAD")&&p==="/icerik-studyo")return html(studio());
 if((m==="GET"||m==="HEAD")&&p==="/urunler")return commerceCatalogPage();
 if((m==="GET"||m==="HEAD")&&p==="/sepet")return commerceCartPage();
 if((m==="GET"||m==="HEAD")&&p.startsWith("/urun/"))return commerceProductPage(decodeURIComponent(p.slice(6)));
 if((m==="GET"||m==="HEAD")&&p==="/markalar")return commerceBrandsPage();
 if((m==="GET"||m==="HEAD")&&p==="/kampanyalar")return commerceCampaignsPage();
 if((m==="GET"||m==="HEAD")&&p==="/teslimat")return commerceDeliveryPage();
 if(m==="GET"&&p==="/api/commerce/account")return commerceAccount(request,env);
 if(m==="GET"&&p==="/api/storefront-v2")return storefront(env);
 if((m==="GET"||m==="HEAD")&&p==="/api/newsletter")return json(await newsletterRead(env));
 if((m==="GET"||m==="HEAD")&&p==="/e-bulten"){
  const response=html(newsletterPage(await newsletterRead(env))),headers=new Headers(response.headers);
  headers.delete('x-frame-options');
  const policy=headers.get('content-security-policy')||'';
  headers.set('content-security-policy',policy.replace(/frame-ancestors[^;]*(;|$)/gi,'')+"; frame-ancestors 'self' https://okyanus-edt-admin.hasan-kaya474.workers.dev");
  return new Response(m==='HEAD'?null:response.body,{status:response.status,headers});
 }
 if(m==="POST"&&p==="/api/newsletter")return newsletterApi(request,env);
 return null;
}

